#include <vector>

class Solution {
public:
    int numSpecial(std::vector<std::vector<int>>& mat) {
        int R = mat.size(), C = mat[0].size();
        std::vector<int> rowSum(R, 0), colSum(C, 0);
        for (int r = 0; r < R; ++r) {
            for (int c = 0; c < C; ++c) {
                rowSum[r] += mat[r][c];
                colSum[c] += mat[r][c];
            }
        }
        int ans = 0;
        for (int r = 0; r < R; ++r) {
            for (int c = 0; c < C; ++c) {
                if (mat[r][c] == 1 && rowSum[r] == 1 && colSum[c] == 1) ans++;
            }
        }
        return ans;
    }
};

